class BigramModel:
    def __init__(self):
        self.counts = {}

    def train(self, text):
        text = text.lower()
        for a, b in zip(text, text[1:]):
            if a not in self.counts:
                self.counts[a] = {}
            self.counts[a][b] = self.counts[a].get(b, 0) + 1

    def next_char(self, ch):
        ch = ch.lower()
        if ch not in self.counts:
            return None
        row = self.counts[ch]
        best = None
        for b in sorted(row):
            if best is None or row[b] > row[best]:
                best = b
        return best

    def __repr__(self):
        total = 0
        for row in self.counts.values():
            total += sum(row.values())
        return f"BigramModel(pairs={total})"


m = BigramModel()
m.train("Hello hello")
print(m)
print(m.next_char("L"))

